body:
GetReadPages 메서드의 진행률 계산 로직에 문제가 있습니다. `reading_progress` 테이블의 `current_page`는 각 챕터의 현재 읽은 페이지를 나타냅니다. 하지만 이를 단순 합산하면 잘못된 결과가 나옵니다. 예를 들어 챕터1(총 10페이지)에서 5페이지까지 읽고, 챕터2(총 10페이지)에서 3페이지까지 읽었다면, 실제 읽은 페이지는 8페이지이지만 SUM(current_page)는 8이 맞습니다. 하지만 챕터1을 완독(10페이지)하고 챕터2를 3페이지까지 읽었다면 실제는 13페이지인데, 데이터는 10+3=13이 맞습니다. 그런데 `series_repository.go`의 동일한 쿼리와 비교해보면, 챕터별 진행도가 저장되어 있을 때 정확하게 계산됩니다. 하지만 완독한 챕터의 경우 reading_progress에 전체 페이지가 저장되는지, 아니면 volume_completions만 체크되는지 확인이 필요합니다. 만약 완독 시 reading_progress가 업데이트되지 않는다면, series_repository.go처럼 completions도 함께 확인해야 합니다.
```suggestion
	// 1) 우선 volume_completions를 조회하여 완독 여부를 확인합니다.
	//    완독된 경우, reading_progress가 더 이상 업데이트되지 않아도 전체 페이지 수로 간주할 수 있습니다.
	var completed bool
	err := database.DB.QueryRow(
		`SELECT EXISTS(
			 SELECT 1
			 FROM volume_completions
			 WHERE user_id = ? AND volume_id = ?
		 )`,
		userID, volumeID,
	).Scan(&completed)
	if err != nil && err != sql.ErrNoRows {
		return 0, err
	}

	// completions가 존재하면 해당 볼륨의 전체 페이지 수를 그대로 반환합니다.
	if completed {
		return r.GetTotalPages(volumeID)
	}

	// 2) 완독이 아닌 경우에만 reading_progress를 합산하여 진행 중인 페이지 수를 계산합니다.
	var progressPages int
	err = database.DB.QueryRow(
		`SELECT COALESCE(SUM(current_page), 0)
		 FROM reading_progress
		 WHERE user_id = ? AND volume_id = ?`,
		userID, volumeID,
	).Scan(&progressPages)
```

